#### 2.2 体态识别引擎 posture-engine.js

```javascript
import { POSTURE_TYPES } from '../common/utils/constants.js'

// 时序特征提取
function extractFeatures(windowData) {
  const axValues = windowData.map(d => d.ax)
  const ayValues = windowData.map(d => d.ay)
  const azValues = windowData.map(d => d.az)

  // 计算均值
  const meanAx = axValues.reduce((a, b) => a + b, 0) / axValues.length
  const meanAy = ayValues.reduce((a, b) => a + b, 0) / ayValues.length
  const meanAz = azValues.reduce((a, b) => a + b, 0) / azValues.length

  // 计算方差
  const varAx = axValues.reduce((a, b) => a + Math.pow(b - meanAx, 2), 0) / axValues.length
  const varAy = ayValues.reduce((a, b) => a + Math.pow(b - meanAy, 2), 0) / ayValues.length
  const varAz = azValues.reduce((a, b) => a + Math.pow(b - meanAz, 2), 0) / azValues.length

  // 合加速度
  const totalAcc = Math.sqrt(meanAx ** 2 + meanAy ** 2 + meanAz ** 2)

  // 俯仰角估算（简化版）
  const pitchAngle = Math.atan2(meanAy, Math.sqrt(meanAx ** 2 + meanAz ** 2)) * 180 / Math.PI

  // 横滚角估算
  const rollAngle = Math.atan2(meanAx, meanAz) * 180 / Math.PI

  return {
    meanAx, meanAy, meanAz,
    varAx, varAy, varAz,
    totalAcc, pitchAngle, rollAngle
  }
}

// 分类模型
function classifyPosture(features) {
  // 规则层：快速筛选
  if (features.pitchAngle > 30) {
    return { type: POSTURE_TYPES.HEAD_DOWN, confidence: 0.92 }
  }

  if (features.rollAngle > 15 && features.varAz > 0.1) {
    return { type: POSTURE_TYPES.CROSS_LEGS, confidence: 0.85 }
  }

  if (features.totalAcc < 0.1 && features.pitchAngle > 15) {
    return { type: POSTURE_TYPES.SEDENTARY, confidence: 0.80 }
  }

  return { type: POSTURE_TYPES.NORMAL, confidence: 0.95 }
}

// 体态识别主函数
export function analyzePosture(sensorData) {
  const windowSize = 100 // 2秒窗口 @ 50Hz
  const features = extractFeatures(sensorData.slice(-windowSize))
  return classifyPosture(features)
}
```

#### 2.3 数据脱敏引擎 desensitizer.js

```javascript
import { DESENSITIZE_RULES } from '../common/utils/constants.js'

// 时间戳脱敏：模糊到小时
function desensitizeTimestamp(timestamp) {
  const date = new Date(timestamp)
  date.setMinutes(0, 0, 0)
  return date.getTime()
}

// 心率脱敏：区间归一化
function desensitizeHeartRate(bpm) {
  const interval = DESENSITIZE_RULES.HEART_RATE.interval
  const lower = Math.floor(bpm / interval) * interval
  return { min: lower, max: lower + interval }
}

// GPS脱敏：网格编码
function desensitizeGPS(lat, lng) {
  const gridSize = DESENSITIZE_RULES.GPS.gridSize / 111000 // 转换为度
  const gridLat = Math.floor(lat / gridSize)
  const gridLng = Math.floor(lng / gridSize)
  return `Grid-${String.fromCharCode(65 + gridLat % 26)}${gridLng}`
}

// 通用脱敏函数
export function desensitize(data, dataType) {
  switch (dataType) {
    case 'heartRate':
      return {
        bpm: desensitizeHeartRate(data.value),
        timestamp: desensitizeTimestamp(data.timeStamp)
      }
    case 'gps':
      return {
        grid: desensitizeGPS(data.lat, data.lng),
        timestamp: desensitizeTimestamp(data.timeStamp)
      }
    case 'posture':
      // 体态数据保留原始特征
      return data
    default:
      return data
  }
}
```

#### 2.4 AES加密引擎 crypto-engine.js

```javascript
import { ENCRYPT_LEVELS } from '../common/utils/constants.js'

// 简化版AES-128-CBC（实际项目中应使用完整的AES实现）
class AESCipher {
  constructor(key) {
    this.key = key
  }

  // PKCS#7填充
  pad(data) {
    const blockSize = 16
    const padLen = blockSize - (data.length % blockSize)
    return data + String.fromCharCode(padLen).repeat(padLen)
  }

  // 加密（模拟实现）
  encrypt(plaintext, iv) {
    const padded = this.pad(plaintext)
    // 实际项目中应使用真正的AES加密
    // 这里使用XOR模拟
    const ciphertext = Array.from(padded).map((char, i) => {
      const keyByte = this.key.charCodeAt(i % this.key.length)
      const ivByte = iv.charCodeAt(i % iv.length)
      return String.fromCharCode(char.charCodeAt(0) ^ keyByte ^ ivByte)
    }).join('')
    return {
      ciphertext: btoa(ciphertext),
      iv: btoa(iv)
    }
  }

  // 解密（模拟实现）
  decrypt(ciphertext, iv) {
    const decoded = atob(ciphertext)
    const plaintext = Array.from(decoded).map((char, i) => {
      const keyByte = this.key.charCodeAt(i % this.key.length)
      const ivByte = iv.charCodeAt(i % iv.length)
      return String.fromCharCode(char.charCodeAt(0) ^ keyByte ^ ivByte)
    }).join('')
    // 移除PKCS#7填充
    const padLen = plaintext.charCodeAt(plaintext.length - 1)
    return plaintext.slice(0, -padLen)
  }
}

// 密钥派生（基于设备唯一ID）
function deriveKey(deviceUID, salt, level) {
  // 简化版密钥派生
  const baseKey = `${deviceUID}-${salt}-${level}`
  // 使用SHA-256哈希的前16字节
  let hash = 0
  for (let i = 0; i < baseKey.length; i++) {
    hash = ((hash << 5) - hash) + baseKey.charCodeAt(i)
    hash |= 0
  }
  return Math.abs(hash).toString(16).padStart(16, '0').slice(0, 16)
}

// 密钥层级
const keyHierarchy = {
  [ENCRYPT_LEVELS.L1]: null,
  [ENCRYPT_LEVELS.L2]: null
}

export function initCrypto(deviceUID) {
  keyHierarchy[ENCRYPT_LEVELS.L1] = deriveKey(deviceUID, 'posture-stats-salt', 'L1')
  keyHierarchy[ENCRYPT_LEVELS.L2] = deriveKey(deviceUID, 'health-privacy-salt', 'L2')
}

export function encrypt(data, level) {
  const key = keyHierarchy[level]
  if (!key) throw new Error('Crypto not initialized')

  const cipher = new AESCipher(key)
  const iv = generateIV()
  return cipher.encrypt(JSON.stringify(data), iv)
}

export function decrypt(encryptedData, level) {
  const key = keyHierarchy[level]
  if (!key) throw new Error('Crypto not initialized')

  const cipher = new AESCipher(key)
  const plaintext = cipher.decrypt(encryptedData.ciphertext, atob(encryptedData.iv))
  return JSON.parse(plaintext)
}

function generateIV() {
  // 生成16字节随机IV
  const iv = new Array(16).fill(0).map(() =>
    String.fromCharCode(Math.floor(Math.random() * 256))
  ).join('')
  return btoa(iv)
}
```

#### 2.5 存储管理器 storage-manager.js

```javascript
import file from '@system.file'
import { encrypt, decrypt } from './crypto-engine.js'
import { ENCRYPT_LEVELS, LIFECYCLE_POLICY } from '../common/utils/constants.js'

// 加密存储
export function saveEncrypted(key, data, options = {}) {
  const { level = ENCRYPT_LEVELS.L1, expiryDays = 30 } = options

  return new Promise((resolve, reject) => {
    const encrypted = encrypt(data, level)
    const metadata = {
      createTime: Date.now(),
      expiryTime: Date.now() + expiryDays * 24 * 60 * 60 * 1000,
      level,
      iv: encrypted.iv
    }

    const fileData = {
      ciphertext: encrypted.ciphertext,
      metadata
    }

    file.writeText({
      uri: `internal://files/${key}.enc`,
      text: JSON.stringify(fileData),
      success: () => resolve(metadata),
      fail: (data, code) => reject(new Error(`Save failed: ${code}`))
    })
  })
}

// 解密读取
export function loadEncrypted(key) {
  return new Promise((resolve, reject) => {
    file.readText({
      uri: `internal://files/${key}.enc`,
      success: (data) => {
        const fileData = JSON.parse(data.text)

        // 检查是否过期
        if (Date.now() > fileData.metadata.expiryTime) {
          return resolve({ expired: true, data: null })
        }

        const decrypted = decrypt({
          ciphertext: fileData.ciphertext,
          iv: fileData.metadata.iv
        }, fileData.metadata.level)

        resolve({ expired: false, data: JSON.parse(decrypted) })
      },
      fail: (data, code) => reject(new Error(`Load failed: ${code}`))
    })
  })
}

// 删除文件
export function deleteFile(key) {
  return new Promise((resolve, reject) => {
    file.delete({
      uri: `internal://files/${key}.enc`,
      success: () => resolve(),
      fail: (data, code) => reject(new Error(`Delete failed: ${code}`))
    })
  })
}

// 清理过期数据
export async function cleanupExpiredData() {
  for (const [dataType, policy] of Object.entries(LIFECYCLE_POLICY)) {
    try {
      const result = await loadEncrypted(dataType)
      if (result.expired) {
        await deleteFile(dataType)
        console.log(`Cleaned up expired data: ${dataType}`)
      }
    } catch (error) {
      console.error(`Cleanup failed for ${dataType}:`, error)
    }
  }
}
```

