import vibrator from '@system.vibrator'
import prompt from '@system.prompt'

// 震动提醒
export function vibrateReminder() {
  return new Promise((resolve) => {
    vibrator.vibrate({
      mode: 'short',  // 200ms短震动
      success: () => {
        console.log('Vibration triggered')
        resolve()
      },
      fail: (data, code) => {
        console.error('Vibration failed:', code)
        resolve()
      }
    })
  })
}

// 弹窗提醒
export function showReminderDialog(postureType) {
  const messages = {
    head_down: '检测到低头前倾，请抬头活动颈椎',
    sedentary: '检测到久坐伏案，请起身活动',
    cross_legs: '检测到跷二郎腿，请调整坐姿'
  }

  return new Promise((resolve) => {
    prompt.showDialog({
      title: '体态提醒',
      message: messages[postureType] || '请注意坐姿',
      buttons: [{ text: '知道了', style: 'default' }],
      success: () => resolve(),
      cancel: () => resolve()
    })
  })
}

// 完整提醒流程
export async function triggerReminder(postureType) {
  // 1. 触发震动
  await vibrateReminder()

  // 2. 显示弹窗
  await showReminderDialog(postureType)

  // 3. 记录提醒事件
  console.log(`Reminder triggered for: ${postureType}`)
}
