<script>
import health from '@service.health'
import { analyzePosture } from '../../modules/posture-engine.js'
import { desensitize } from '../../modules/desensitizer.js'
import { saveEncrypted } from '../../modules/storage-manager.js'
import { triggerReminder } from '../../modules/reminder-manager.js'
import { generateMockData } from '../../modules/mock-sensor.js'

export default {
  private: {
    healthScore: 85,
    todayStats: {
      totalCount: 0,
      headDown: 0,
      sedentary: 0,
      crossLegs: 0
    },
    recentReminders: [],
    isMonitoring: false,
    sensorDataBuffer: [],
    lastReminderTime: 0
  },

  onReady() {
    this.loadTodayStats()
    this.startHealthDataSubscription()
  },

  onDestroy() {
    this.stopMonitoring()
  },

  // 加载今日统计
  async loadTodayStats() {
    // 从加密存储中加载今日统计
    // 这里简化处理
  },

  // 订阅健康数据
  startHealthDataSubscription() {
    health.subscribeSample({
      dataType: health.DATA_TYPES.HEART_RATE,
      callback: (sample) => {
        // 脱敏处理
        const desensitized = desensitize(sample, 'heartRate')
        console.log('Heart rate:', desensitized)

        // 加密存储
        saveEncrypted('heart_rate_latest', desensitized, { level: 'level2', expiryDays: 7 })
      },
      fail: (data, code) => {
        console.log('Health subscription failed:', code)
      }
    })
  },

  // 切换监测状态
  toggleMonitoring() {
    if (this.isMonitoring) {
      this.stopMonitoring()
    } else {
      this.startMonitoring()
    }
  },

  // 开始监测
  startMonitoring() {
    this.isMonitoring = true

    // 使用Mock数据模拟传感器
    const mockData = generateMockData('headDown', 60000) // 1分钟数据

    let index = 0
    const interval = setInterval(() => {
      if (index >= mockData.length || !this.isMonitoring) {
        clearInterval(interval)
        return
      }

      this.sensorDataBuffer.push(mockData[index])
      index++

      // 每100帧分析一次
      if (this.sensorDataBuffer.length >= 100) {
        const result = analyzePosture(this.sensorDataBuffer)

        if (result.type !== 'normal') {
          this.handlePostureAlert(result.type)
        }

        this.sensorDataBuffer = this.sensorDataBuffer.slice(-50) // 保留50帧滑动窗口
      }
    }, 20)
  },

  // 停止监测
  stopMonitoring() {
    this.isMonitoring = false
    this.sensorDataBuffer = []
  },

  // 处理体态异常
  async handlePostureAlert(postureType) {
    const now = Date.now()

    // 冷却时间检查（5分钟）
    if (now - this.lastReminderTime < 5 * 60 * 1000) {
      return
    }

    this.lastReminderTime = now

    // 更新统计
    this.todayStats.totalCount++
    this.todayStats[postureType] = (this.todayStats[postureType] || 0) + 1

    // 触发提醒
    await triggerReminder(postureType)

    // 记录提醒
    this.recentReminders.unshift({
      time: new Date().toLocaleTimeString(),
      type: postureType
    })

    // 保持最近5条记录
    if (this.recentReminders.length > 5) {
      this.recentReminders.pop()
    }

    // 保存统计到加密存储
    saveEncrypted('today_stats', this.todayStats, { level: 'level1', expiryDays: 30 })

    // 计算健康评分
    this.calculateHealthScore()
  },

  // 计算健康评分
  calculateHealthScore() {
    const { totalCount } = this.todayStats
    // 简化评分逻辑：异常次数越多，分数越低
    this.healthScore = Math.max(0, 100 - totalCount * 5)
  }
}
</script>

