// 集成测试脚本
import { generateMockData } from './mock-sensor.js'
import { analyzePosture } from './posture-engine.js'
import { desensitize } from './desensitizer.js'
import { encrypt, decrypt, initCrypto } from './crypto-engine.js'
import { saveEncrypted, loadEncrypted, deleteFile } from './storage-manager.js'

// 测试套件
const tests = {
  passed: 0,
  failed: 0,
  total: 0
}

function assert(condition, testName) {
  tests.total++
  if (condition) {
    tests.passed++
    console.log(`✓ ${testName}`)
  } else {
    tests.failed++
    console.log(`✗ ${testName}`)
  }
}

// 测试1: Mock数据生成
console.log('\n=== 测试1: Mock数据生成 ===')
const mockData = generateMockData('headDown', 2000)
assert(mockData.length === 100, '生成正确数量的样本 (100个/2秒)')
assert(mockData[0].ax !== undefined, '样本包含ax字段')
assert(mockData[0].ay !== undefined, '样本包含ay字段')
assert(mockData[0].az !== undefined, '样本包含az字段')
assert(mockData[0].timestamp !== undefined, '样本包含timestamp字段')

// 测试2: 体态识别
console.log('\n=== 测试2: 体态识别 ===')
const headDownData = generateMockData('headDown', 2000)
const headDownResult = analyzePosture(headDownData)
assert(headDownResult.type === 'head_down', '识别低头前倾体态')
assert(headDownResult.confidence > 0.8, '置信度大于0.8')

const sedentaryData = generateMockData('sedentary', 2000)
const sedentaryResult = analyzePosture(sedentaryData)
assert(sedentaryResult.type === 'sedentary', '识别久坐伏案体态')

// 测试3: 数据脱敏
console.log('\n=== 测试3: 数据脱敏 ===')
const heartRateData = { value: 72, timeStamp: Date.now() }
const desensitizedHR = desensitize(heartRateData, 'heartRate')
assert(desensitizedHR.bpm.min === 70, '心率下限正确')
assert(desensitizedHR.bpm.max === 75, '心率上限正确')
assert(desensitizedHR.timestamp !== heartRateData.timeStamp, '时间戳已脱敏')

const gpsData = { lat: 39.916, lng: 116.397, timeStamp: Date.now() }
const desensitizedGPS = desensitize(gpsData, 'gps')
assert(desensitizedGPS.grid.startsWith('Grid-'), 'GPS网格编码格式正确')

