assert(encrypted.ciphertext !== undefined, '加密结果包含ciphertext')
assert(encrypted.iv !== undefined, '加密结果包含iv')

const decrypted = decrypt(encrypted, 'level1')
assert(JSON.stringify(testData) === JSON.stringify(decrypted), '解密结果与原文一致')

