const encryptedL1 = encrypt(testData, 'level1')
const encryptedL2 = encrypt(testData, 'level2')
assert(encryptedL1.ciphertext !== encryptedL2.ciphertext, '不同等级加密结果不同')

// 测试6: 性能测试
console.log('\n=== 测试6: 性能测试 ===')
const startTime = Date.now()
for (let i = 0; i < 1000; i++) {
  encrypt({ data: i }, 'level1')
}
const encryptTime = Date.now() - startTime
assert(encryptTime < 1000, `加密1000次耗时 ${encryptTime}ms < 1000ms`)

const startDecryptTime = Date.now()
for (let i = 0; i < 1000; i++) {
  decrypt(encryptedL1, 'level1')
}
