console.log(`通过: ${tests.passed}/${tests.total}`)
console.log(`失败: ${tests.failed}/${tests.total}`)
console.log(`成功率: ${((tests.passed / tests.total) * 100).toFixed(2)}%`)

if (tests.failed === 0) {
  console.log('\n🎉 所有测试通过！')
} else {
  console.log('\n❌ 有测试失败，请检查代码')
}

// 性能优化工具
export class PerformanceOptimizer {
  constructor() {
    this.memoryThreshold = 2 * 1024 * 1024 // 2MB
    this.storageThreshold = 5 * 1024 * 1024 // 5MB
    this.sampleBuffer = []
    this.maxBufferSize = 200 // 最大缓冲区大小
  }

  // 内存优化：限制缓冲区大小
  optimizeBufferSize(buffer) {
    if (buffer.length > this.maxBufferSize) {
      return buffer.slice(-this.maxBufferSize)
    }
    return buffer
  }

  // 功耗优化：根据场景调整采样频率
  adjustSamplingRate(isForeground, isMoving) {
    if (!isForeground) {
      return 10 // 后台10Hz
    }
    if (!isMoving) {
      return 20 // 静止20Hz
    }
    return 50 // 前台运动50Hz
  }

  // 存储优化：压缩数据
  compressData(data) {
    // 简单压缩：移除冗余字段
    const compressed = {
      t: data.timestamp,
      a: [data.ax, data.ay, data.az],
      g: [data.gx, data.gy, data.gz]
    }
    return compressed
  }

  // 存储优化：批量写入
  async batchWrite(items, writeFn) {
    const batchSize = 10
    for (let i = 0; i < items.length; i += batchSize) {
      const batch = items.slice(i, i + batchSize)
      await Promise.all(batch.map(item => writeFn(item)))
    }
  }

  // 清理策略：定时清理
  setupCleanupScheduler(cleanupFn, intervalMs = 60000) {
    setInterval(() => {
      cleanupFn()
    }, intervalMs)
  }

  // 监控内存使用
  monitorMemory() {
    // 在快应用环境中，可以使用console.log输出内存信息
    console.log('[Performance] Memory monitoring active')
  }
}

export default new PerformanceOptimizer()

/**
