  BATCH_SIZE: 10, // 批量写入大小
  CLEANUP_INTERVAL: 60000, // 清理间隔（毫秒）
  MAX_STORAGE_SIZE: 5 * 1024 * 1024 // 最大存储空间（5MB）
}

// UI配置
export const UI_CONFIG = {
