  MAX_REMINDERS: 5, // 最大提醒记录数
  ANIMATION_DURATION: 300, // 动画时长（毫秒）
  TOAST_DURATION: 2000 // 提示显示时长（毫秒）
}

// 错误码定义
export const ERROR_CODES = {
  SUCCESS: 0,
  UNKNOWN: 1,
  INVALID_PARAM: 2,
  NOT_INITIALIZED: 3,
  STORAGE_FULL: 4,
  ENCRYPTION_FAILED: 5,
  DECRYPTION_FAILED: 6,
  SENSOR_UNAVAILABLE: 7,
  HEALTH_DATA_UNAVAILABLE: 8
}

// 错误消息映射
export const ERROR_MESSAGES = {
  [ERROR_CODES.SUCCESS]: '操作成功',
  [ERROR_CODES.UNKNOWN]: '未知错误',
  [ERROR_CODES.INVALID_PARAM]: '参数无效',
  [ERROR_CODES.NOT_INITIALIZED]: '模块未初始化',
  [ERROR_CODES.STORAGE_FULL]: '存储空间不足',
  [ERROR_CODES.ENCRYPTION_FAILED]: '加密失败',
  [ERROR_CODES.DECRYPTION_FAILED]: '解密失败',
  [ERROR_CODES.SENSOR_UNAVAILABLE]: '传感器不可用',
  [ERROR_CODES.HEALTH_DATA_UNAVAILABLE]: '健康数据不可用'
}

/**
 * 通用工具函数
 * 提供常用的辅助功能
 */

/**
 * 延迟执行
 * @param {number} ms - 延迟毫秒数
 * @returns {Promise} 延迟Promise
 */
export function delay(ms) {
  return new Promise(resolve => setTimeout(resolve, ms))
}

/**
 * 格式化时间戳
 * @param {number} timestamp - 时间戳
 * @param {string} format - 格式化模式
 * @returns {string} 格式化后的时间字符串
 */
export function formatTimestamp(timestamp, format = 'HH:mm:ss') {
  const date = new Date(timestamp)
  const hours = date.getHours().toString().padStart(2, '0')
  const minutes = date.getMinutes().toString().padStart(2, '0')
  const seconds = date.getSeconds().toString().padStart(2, '0')
  const year = date.getFullYear()
  const month = (date.getMonth() + 1).toString().padStart(2, '0')
  const day = date.getDate().toString().padStart(2, '0')

  switch (format) {
    case 'HH:mm:ss':
      return `${hours}:${minutes}:${seconds}`
    case 'YYYY-MM-DD':
      return `${year}-${month}-${day}`
    case 'YYYY-MM-DD HH:mm:ss':
      return `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`
    case 'MM-DD HH:mm':
      return `${month}-${day} ${hours}:${minutes}`
    default:
      return `${hours}:${minutes}:${seconds}`
  }
}

/**
 * 生成唯一ID
 * @returns {string} 唯一ID
 */
export function generateUniqueId() {
  return `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`
}

/**
 * 深拷贝对象
 * @param {Object} obj - 源对象
 * @returns {Object} 拷贝后的对象
 */
export function deepClone(obj) {
  if (obj === null || typeof obj !== 'object') {
    return obj
  }

  if (obj instanceof Date) {
    return new Date(obj.getTime())
  }

  if (obj instanceof Array) {
    return obj.map(item => deepClone(item))
  }

  if (typeof obj === 'object') {
    const clonedObj = {}
    for (const key in obj) {
      if (obj.hasOwnProperty(key)) {
        clonedObj[key] = deepClone(obj[key])
      }
    }
    return clonedObj
  }

  return obj
}

/**
 * 防抖函数
 * @param {Function} func - 要防抖的函数
 * @param {number} wait - 等待时间
 * @returns {Function} 防抖后的函数
 */
export function debounce(func, wait) {
  let timeout
  return function executedFunction(...args) {
    const later = () => {
      clearTimeout(timeout)
      func(...args)
    }
    clearTimeout(timeout)
    timeout = setTimeout(later, wait)
  }
}

/**
 * 节流函数
 * @param {Function} func - 要节流的函数
 * @param {number} limit - 限制时间
 * @returns {Function} 节流后的函数
 */
export function throttle(func, limit) {
  let inThrottle
  return function executedFunction(...args) {
    if (!inThrottle) {
      func(...args)
      inThrottle = true
      setTimeout(() => inThrottle = false, limit)
    }
  }
}

/**
 * 计算两个时间戳之间的差异
 * @param {number} start - 开始时间戳
 * @param {number} end - 结束时间戳
 * @returns {Object} 时间差异对象
 */
export function getTimeDifference(start, end) {
  const diff = Math.abs(end - start)
  const seconds = Math.floor(diff / 1000)
  const minutes = Math.floor(seconds / 60)
  const hours = Math.floor(minutes / 60)
  const days = Math.floor(hours / 24)

  return {
    milliseconds: diff % 1000,
    seconds: seconds % 60,
    minutes: minutes % 60,
    hours: hours % 24,
    days,
    total: diff
  }
}

/**
 * 格式化持续时间
 * @param {number} milliseconds - 毫秒数
 * @returns {string} 格式化后的持续时间
 */
export function formatDuration(milliseconds) {
  const { days, hours, minutes, seconds } = getTimeDifference(0, milliseconds)

  if (days > 0) {
    return `${days}天${hours}小时${minutes}分钟`
  }
  if (hours > 0) {
    return `${hours}小时${minutes}分钟`
  }
  if (minutes > 0) {
    return `${minutes}分钟${seconds}秒`
  }
  return `${seconds}秒`
}

/**
 * 计算健康评分
 * @param {Object} stats - 统计数据
 * @returns {number} 健康评分（0-100）
 */
export function calculateHealthScore(stats) {
  const { totalCount = 0 } = stats

  // 基础分数
  let score = 100

  // 根据异常次数扣分
  score -= Math.min(totalCount * 5, 50) // 最多扣50分

  // 确保分数在0-100之间
  return Math.max(0, Math.min(100, score))
}

/**
 * 验证数据格式
 * @param {Object} data - 要验证的数据
 * @param {Object} schema - 数据模式
 * @returns {Object} 验证结果
 */
export function validateData(data, schema) {
  const errors = []

  for (const [key, rules] of Object.entries(schema)) {
    const value = data[key]

    // 检查必填字段
    if (rules.required && (value === undefined || value === null)) {
      errors.push(`${key} 是必填字段`)
      continue
    }

    // 检查类型
    if (value !== undefined && rules.type && typeof value !== rules.type) {
      errors.push(`${key} 类型错误，期望 ${rules.type}，实际 ${typeof value}`)
    }

    // 检查范围
    if (value !== undefined && rules.min !== undefined && value < rules.min) {
      errors.push(`${key} 不能小于 ${rules.min}`)
    }

    if (value !== undefined && rules.max !== undefined && value > rules.max) {
      errors.push(`${key} 不能大于 ${rules.max}`)
    }
  }

  return {
    valid: errors.length === 0,
    errors
  }
}

/**
 * 安全的JSON解析
 * @param {string} jsonString - JSON字符串
 * @param {*} defaultValue - 默认值
 * @returns {*} 解析后的对象
 */
export function safeJsonParse(jsonString, defaultValue = null) {
  try {
    return JSON.parse(jsonString)
  } catch (error) {
    console.error('[Helpers] JSON解析失败:', error)
    return defaultValue
  }
}

/**
 * 安全的JSON字符串化
 * @param {*} obj - 对象
 * @param {string} defaultValue - 默认值
 * @returns {string} JSON字符串
 */
export function safeJsonStringify(obj, defaultValue = '{}') {
  try {
    return JSON.stringify(obj)
  } catch (error) {
    console.error('[Helpers] JSON字符串化失败:', error)
    return defaultValue
  }
}

/**
 * 获取当前时间的小时数
 * @returns {number} 小时数（0-23）
 */
export function getCurrentHour() {
  return new Date().getHours()
}

/**
 * 判断是否是夜间模式
 * @returns {boolean} 是否是夜间模式
 */
export function isNightMode() {
  const hour = getCurrentHour()
  return hour >= 22 || hour < 7
}

/**
 * 生成随机数
 * @param {number} min - 最小值
 * @param {number} max - 最大值
 * @returns {number} 随机数
 */
export function random(min, max) {
  return Math.floor(Math.random() * (max - min + 1)) + min
}

/**
 * 限制数组大小
 * @param {Array} arr - 数组
 * @param {number} maxSize - 最大大小
 * @returns {Array} 限制大小后的数组
 */
export function limitArraySize(arr, maxSize) {
  if (arr.length <= maxSize) {
    return arr
  }
  return arr.slice(-maxSize)
}

/**
 * 日志工具
 * 提供统一的日志记录和错误处理
 */

import { formatTimestamp } from './helpers.js'

// 日志级别
const LOG_LEVELS = {
  DEBUG: 0,
  INFO: 1,
  WARN: 2,
  ERROR: 3,
  FATAL: 4
}

// 日志级别标签
const LOG_LEVEL_LABELS = {
  [LOG_LEVELS.DEBUG]: 'DEBUG',
  [LOG_LEVELS.INFO]: 'INFO',
  [LOG_LEVELS.WARN]: 'WARN',
  [LOG_LEVELS.ERROR]: 'ERROR',
  [LOG_LEVELS.FATAL]: 'FATAL'
}

// 日志颜色（用于控制台输出）
const LOG_COLORS = {
  [LOG_LEVELS.DEBUG]: '#888888',
  [LOG_LEVELS.INFO]: '#2196F3',
  [LOG_LEVELS.WARN]: '#FF9800',
  [LOG_LEVELS.ERROR]: '#F44336',
  [LOG_LEVELS.FATAL]: '#9C27B0'
}

class Logger {
  constructor(moduleName = 'App') {
    this.moduleName = moduleName
    this.minLevel = LOG_LEVELS.DEBUG
    this.logs = []
    this.maxLogs = 1000
  }

  /**
   * 设置最小日志级别
   * @param {number} level - 日志级别
   */
  setMinLevel(level) {
    this.minLevel = level
  }

  /**
   * 格式化日志消息
   * @param {number} level - 日志级别
   * @param {string} message - 日志消息
   * @param {Object} data - 附加数据
   * @returns {string} 格式化后的日志消息
   */
  formatMessage(level, message, data = null) {
    const timestamp = formatTimestamp(Date.now(), 'YYYY-MM-DD HH:mm:ss')
    const levelLabel = LOG_LEVEL_LABELS[level]
    const prefix = `[${timestamp}] [${levelLabel}] [${this.moduleName}]`

    let formattedMessage = `${prefix} ${message}`

    if (data) {
      const dataStr = typeof data === 'object' ? JSON.stringify(data) : String(data)
      formattedMessage += ` | ${dataStr}`
    }

    return formattedMessage
  }

  /**
   * 记录日志
   * @param {number} level - 日志级别
   * @param {string} message - 日志消息
   * @param {Object} data - 附加数据
   */
  log(level, message, data = null) {
    if (level < this.minLevel) {
      return
    }

    const formattedMessage = this.formatMessage(level, message, data)

    // 存储日志
    this.logs.push({
      timestamp: Date.now(),
      level,
      message,
      data,
      formatted: formattedMessage
    })

    // 限制日志数量
    if (this.logs.length > this.maxLogs) {
      this.logs.shift()
    }

    // 控制台输出
    this.consoleOutput(level, formattedMessage)
  }

  /**
   * 控制台输出
   * @param {number} level - 日志级别
   * @param {string} message - 日志消息
   */
  consoleOutput(level, message) {
    const color = LOG_COLORS[level]

    switch (level) {
      case LOG_LEVELS.DEBUG:
        console.log(`%c${message}`, `color: ${color}`)
        break
      case LOG_LEVELS.INFO:
        console.log(`%c${message}`, `color: ${color}; font-weight: bold`)
        break
      case LOG_LEVELS.WARN:
        console.warn(`%c${message}`, `color: ${color}; font-weight: bold`)
        break
      case LOG_LEVELS.ERROR:
        console.error(`%c${message}`, `color: ${color}; font-weight: bold`)
        break
      case LOG_LEVELS.FATAL:
        console.error(`%c${message}`, `color: ${color}; font-weight: bold; font-size: 14px`)
        break
      default:
        console.log(message)
    }
  }

  /**
   * 调试日志
   * @param {string} message - 日志消息
   * @param {Object} data - 附加数据
   */
  debug(message, data = null) {
    this.log(LOG_LEVELS.DEBUG, message, data)
  }

  /**
   * 信息日志
   * @param {string} message - 日志消息
   * @param {Object} data - 附加数据
   */
  info(message, data = null) {
    this.log(LOG_LEVELS.INFO, message, data)
  }

  /**
   * 警告日志
   * @param {string} message - 日志消息
   * @param {Object} data - 附加数据
   */
  warn(message, data = null) {
    this.log(LOG_LEVELS.WARN, message, data)
  }

  /**
   * 错误日志
   * @param {string} message - 日志消息
   * @param {Object} data - 附加数据
   */
  error(message, data = null) {
    this.log(LOG_LEVELS.ERROR, message, data)
  }

  /**
   * 致命错误日志
   * @param {string} message - 日志消息
   * @param {Object} data - 附加数据
   */
  fatal(message, data = null) {
    this.log(LOG_LEVELS.FATAL, message, data)
  }

  /**
   * 获取日志历史
   * @param {number} level - 可选，过滤日志级别
   * @param {number} limit - 可选，限制数量
   * @returns {Array} 日志历史
   */
  getLogs(level = null, limit = null) {
    let filteredLogs = this.logs

    if (level !== null) {
      filteredLogs = filteredLogs.filter(log => log.level === level)
    }

    if (limit !== null) {
      filteredLogs = filteredLogs.slice(-limit)
    }

    return filteredLogs
  }

  /**
   * 清空日志
   */
  clearLogs() {
    this.logs = []
  }

  /**
   * 导出日志
   * @returns {string} JSON格式的日志
   */
  exportLogs() {
    return JSON.stringify(this.logs, null, 2)
  }
}

