// 缓存生成的数据
const dataCache = new Map()

/**
 * 生成单个传感器数据点
 * @param {string} scenario - 场景类型
 * @param {number} time - 时间（秒）
 * @returns {Object} 传感器数据
 */
function generateSingleSample(scenario, time) {
  const scenarioConfig = SCENARIOS[scenario]
  if (!scenarioConfig) {
    throw new Error(`未知场景: ${scenario}`)
  }

  const sample = scenarioConfig.generate(time)
  return {
    ...sample,
    timestamp: Date.now() + time * 1000
  }
}

/**
 * 生成模拟传感器数据
 * @param {string} scenario - 场景类型
 * @param {number} duration - 持续时间（毫秒）
 * @param {Object} options - 配置选项
 * @returns {Array} 传感器数据数组
 */
export function generateMockData(scenario, duration, options = {}) {
  const {
    samplingRate = SENSOR_CONFIG.SAMPLING_RATE,
    useCache = true
  } = options

  // 检查缓存
  const cacheKey = `${scenario}_${duration}_${samplingRate}`
  if (useCache && dataCache.has(cacheKey)) {
    logger.debug('使用缓存数据', { cacheKey })
    return dataCache.get(cacheKey)
  }

  const data = []
  const startTime = Date.now()
  const sampleInterval = 1000 / samplingRate // 毫秒

  logger.debug('开始生成Mock数据', {
    scenario,
    duration,
    samplingRate,
    sampleInterval
  })

  for (let t = 0; t < duration; t += sampleInterval) {
    const sample = generateSingleSample(scenario, t / 1000)
    data.push(sample)
  }

  // 缓存生成的数据
  if (useCache) {
    dataCache.set(cacheKey, data)
  }

  logger.info('Mock数据生成完成', {
    scenario,
    sampleCount: data.length,
    duration: data.length * sampleInterval
  })

  return data
}

/**
 * 生成混合场景数据
 * @param {Array} scenes - 场景配置数组 [{scenario, duration}]
 * @param {Object} options - 配置选项
 * @returns {Array} 混合场景数据数组
 */
export function generateMixedMockData(scenes, options = {}) {
  const allData = []
  let offset = 0

  for (const scene of scenes) {
    const { scenario, duration } = scene
    const data = generateMockData(scenario, duration, options)

    // 调整时间戳偏移
    const adjustedData = data.map((sample, index) => ({
      ...sample,
      timestamp: sample.timestamp + offset
    }))

    allData.push(...adjustedData)
    offset += duration
  }

  logger.info('混合场景数据生成完成', {
    totalSamples: allData.length,
    scenes: scenes.map(s => s.scenario)
  })

  return allData
}

