/**
 * 体态识别引擎
 * 基于时序特征提取和规则分类的体态识别算法
 */

import { POSTURE_TYPES, SENSOR_CONFIG, ERROR_CODES } from '../common/utils/constants.js'
import { logger } from '../common/utils/logger.js'

// 缓存计算结果
const featureCache = new Map()

/**
 * 计算数组均值
 * @param {Array} arr - 数组
 * @returns {number} 均值
 */
function calculateMean(arr) {
  if (arr.length === 0) return 0
  let sum = 0
  for (let i = 0; i < arr.length; i++) {
    sum += arr[i]
  }
  return sum / arr.length
}

/**
 * 计算数组方差
 * @param {Array} arr - 数组
 * @param {number} mean - 均值（可选，避免重复计算）
 * @returns {number} 方差
 */
function calculateVariance(arr, mean = null) {
  if (arr.length === 0) return 0
  if (mean === null) mean = calculateMean(arr)

  let sumSquaredDiff = 0
  for (let i = 0; i < arr.length; i++) {
    const diff = arr[i] - mean
    sumSquaredDiff += diff * diff
  }
  return sumSquaredDiff / arr.length
}

/**
 * 计算合加速度
 * @param {number} ax - X轴加速度
 * @param {number} ay - Y轴加速度
 * @param {number} az - Z轴加速度
 * @returns {number} 合加速度
 */
function calculateTotalAcceleration(ax, ay, az) {
  return Math.sqrt(ax * ax + ay * ay + az * az)
}

/**
 * 计算俯仰角（Pitch）
 * @param {number} ay - Y轴加速度
 * @param {number} ax - X轴加速度
 * @param {number} az - Z轴加速度
 * @returns {number} 俯仰角（度）
 */
function calculatePitchAngle(ay, ax, az) {
  return Math.atan2(ay, Math.sqrt(ax * ax + az * az)) * 180 / Math.PI
}

/**
 * 计算横滚角（Roll）
 * @param {number} ax - X轴加速度
 * @param {number} az - Z轴加速度
 * @returns {number} 横滚角（度）
 */
function calculateRollAngle(ax, az) {
  return Math.atan2(ax, az) * 180 / Math.PI
}

/**
 * 提取时序特征
 * @param {Array} windowData - 窗口数据
 * @returns {Object} 特征向量
 */
function extractFeatures(windowData) {
  if (!windowData || windowData.length === 0) {
    return null
  }

  // 检查缓存
  const cacheKey = windowData.map(d => `${d.ax},${d.ay},${d.az}`).join('|')
  if (featureCache.has(cacheKey)) {
    return featureCache.get(cacheKey)
  }

  // 提取各轴数据
  const axValues = []
  const ayValues = []
  const azValues = []

  for (let i = 0; i < windowData.length; i++) {
    axValues.push(windowData[i].ax)
    ayValues.push(windowData[i].ay)
    azValues.push(windowData[i].az)
  }

  // 计算均值
  const meanAx = calculateMean(axValues)
  const meanAy = calculateMean(ayValues)
  const meanAz = calculateMean(azValues)

  // 计算方差
  const varAx = calculateVariance(axValues, meanAx)
  const varAy = calculateVariance(ayValues, meanAy)
  const varAz = calculateVariance(azValues, meanAz)

  // 计算合加速度
  const totalAcc = calculateTotalAcceleration(meanAx, meanAy, meanAz)

  // 计算姿态角
  const pitchAngle = calculatePitchAngle(meanAy, meanAx, meanAz)
  const rollAngle = calculateRollAngle(meanAx, meanAz)

  const features = {
    meanAx,
    meanAy,
    meanAz,
    varAx,
    varAy,
    varAz,
    totalAcc,
    pitchAngle,
    rollAngle
  }

  // 缓存结果
  featureCache.set(cacheKey, features)

  // 限制缓存大小
  if (featureCache.size > 1000) {
    const firstKey = featureCache.keys().next().value
    featureCache.delete(firstKey)
  }

  return features
}

/**
 * 分类体态类型
 * @param {Object} features - 特征向量
 * @returns {Object} 分类结果
 */
function classifyPosture(features) {
  if (!features) {
    return { type: POSTURE_TYPES.NORMAL, confidence: 0.5 }
  }

  const { pitchAngle, rollAngle, varAz, totalAcc } = features
  const confidenceThreshold = SENSOR_CONFIG.CONFIDENCE_THRESHOLD

  // 规则层：快速筛选
  // 低头前倾：俯仰角大于30度
  if (pitchAngle > 30) {
    const confidence = Math.min(0.95, 0.85 + (pitchAngle - 30) / 100)
    return { type: POSTURE_TYPES.HEAD_DOWN, confidence }
  }

  // 跷二郎腿：横滚角大于15度且Z轴方差较大
  if (rollAngle > 15 && varAz > 0.1) {
    const confidence = Math.min(0.90, 0.75 + (rollAngle - 15) / 100)
    return { type: POSTURE_TYPES.CROSS_LEGS, confidence }
  }

  // 久坐伏案：合加速度小于0.1g且俯仰角大于15度
  if (totalAcc < 0.1 && pitchAngle > 15) {
    const confidence = Math.min(0.85, 0.70 + (15 - pitchAngle) / 100)
    return { type: POSTURE_TYPES.SEDENTARY, confidence }
  }

  // 正常体态
  return { type: POSTURE_TYPES.NORMAL, confidence: 0.95 }
}

/**
 * 分析体态
 * @param {Array} sensorData - 传感器数据数组
 * @param {Object} options - 配置选项
 * @returns {Object} 分析结果
 */
export function analyzePosture(sensorData, options = {}) {
  const {
    windowSize = SENSOR_CONFIG.WINDOW_SIZE,
    validateData = true
  } = options

  // 数据验证
  if (validateData && (!sensorData || !Array.isArray(sensorData))) {
    logger.warn('体态分析数据无效', { sensorData })
    return {
      type: POSTURE_TYPES.NORMAL,
      confidence: 0.5,
      error: ERROR_CODES.INVALID_PARAM
    }
  }

  if (sensorData.length === 0) {
    logger.warn('传感器数据为空')
    return {
      type: POSTURE_TYPES.NORMAL,
      confidence: 0.5,
      error: ERROR_CODES.INVALID_PARAM
    }
  }

  // 获取窗口数据
  const windowData = sensorData.slice(-windowSize)

  // 提取特征
  const features = extractFeatures(windowData)

  // 分类体态
  const result = classifyPosture(features)

  logger.debug('体态分析完成', {
    dataLength: sensorData.length,
    windowSize: windowData.length,
    features: features ? {
      pitchAngle: features.pitchAngle.toFixed(2),
      rollAngle: features.rollAngle.toFixed(2),
      totalAcc: features.totalAcc.toFixed(4)
    } : null,
    result
  })

  return result
}

/**
 * 批量分析体态
 * @param {Array} sensorData - 传感器数据数组
 * @param {number} batchSize - 批次大小
 * @returns {Array} 分析结果数组
 */
export function analyzePostureBatch(sensorData, batchSize = 100) {
  const results = []

  for (let i = 0; i < sensorData.length; i += batchSize) {
    const batch = sensorData.slice(0, i + batchSize)
    const result = analyzePosture(batch)
    results.push(result)
  }

  logger.info('批量体态分析完成', {
    totalSamples: sensorData.length,
    batchSize,
    resultCount: results.length
  })

  return results
}

/**
 * 清空特征缓存
 */
export function clearFeatureCache() {
  featureCache.clear()
  logger.debug('特征缓存已清空')
}

/**
 * 获取体态类型统计
 * @param {Array} results - 分析结果数组
 * @returns {Object} 统计结果
 */
export function getPostureStatistics(results) {
  const stats = {
    [POSTURE_TYPES.NORMAL]: 0,
    [POSTURE_TYPES.HEAD_DOWN]: 0,
    [POSTURE_TYPES.SEDENTARY]: 0,
    [POSTURE_TYPES.CROSS_LEGS]: 0,
    total: results.length
  }

  for (const result of results) {
    if (stats.hasOwnProperty(result.type)) {
      stats[result.type]++
    }
  }

  // 计算百分比
  const percentages = {}
  for (const [type, count] of Object.entries(stats)) {
    if (type !== 'total') {
      percentages[type] = stats.total > 0 ? (count / stats.total * 100).toFixed(2) : 0
    }
  }

  return { counts: stats, percentages }
}

/**
 * AES加密引擎
 * 提供AES-128-CBC加密和解密功能
 */

import { ENCRYPT_LEVELS, ERROR_CODES } from '../common/utils/constants.js'
import { logger } from '../common/utils/logger.js'
import { safeJsonStringify, safeJsonParse } from '../common/utils/helpers.js'

// 密钥层级
const keyHierarchy = {
  [ENCRYPT_LEVELS.L1]: null,
  [ENCRYPT_LEVELS.L2]: null
}

// 加密状态
let isInitialized = false

/**
 * 简化版AES-128-CBC加密器
 * 注意：这是演示版本，生产环境应使用完整的AES实现
 */
class AESCipher {
  constructor(key) {
    this.key = key
    this.blockSize = 16
  }

  /**
   * PKCS#7填充
   * @param {string} data - 待填充数据
   * @returns {string} 填充后的数据
   */
  pad(data) {
    const padLen = this.blockSize - (data.length % this.blockSize)
    const padChar = String.fromCharCode(padLen)
    return data + padChar.repeat(padLen)
  }

  /**
   * 移除PKCS#7填充
   * @param {string} data - 带填充的数据
   * @returns {string} 移除填充后的数据
   */
  unpad(data) {
    const padLen = data.charCodeAt(data.length - 1)
    if (padLen > this.blockSize || padLen === 0) {
      throw new Error('无效的填充')
    }
    return data.slice(0, -padLen)
  }

  /**
   * 加密数据
   * @param {string} plaintext - 明文
   * @param {string} iv - 初始化向量
   * @returns {Object} 加密结果
   */
  encrypt(plaintext, iv) {
    const padded = this.pad(plaintext)
    const ciphertext = []

    for (let i = 0; i < padded.length; i++) {
      const keyByte = this.key.charCodeAt(i % this.key.length)
      const ivByte = iv.charCodeAt(i % iv.length)
      const plainByte = padded.charCodeAt(i)
      ciphertext.push(String.fromCharCode(plainByte ^ keyByte ^ ivByte))
    }

    return {
      ciphertext: btoa(ciphertext.join('')),
      iv: btoa(iv)
    }
  }

  /**
   * 解密数据
   * @param {string} ciphertext - 密文（Base64编码）
   * @param {string} iv - 初始化向量（Base64编码）
   * @returns {string} 明文
   */
  decrypt(ciphertext, iv) {
    const decoded = atob(ciphertext)
    const ivDecoded = atob(iv)
    const plaintext = []

    for (let i = 0; i < decoded.length; i++) {
      const keyByte = this.key.charCodeAt(i % this.key.length)
      const ivByte = ivDecoded.charCodeAt(i % ivDecoded.length)
      const cipherByte = decoded.charCodeAt(i)
      plaintext.push(String.fromCharCode(cipherByte ^ keyByte ^ ivByte))
    }

    return this.unpad(plaintext.join(''))
  }
}

/**
 * 生成随机IV
 * @returns {string} 16字节随机IV（Base64编码）
 */
function generateIV() {
  const iv = new Array(16).fill(0).map(() =>
    String.fromCharCode(Math.floor(Math.random() * 256))
  ).join('')
  return btoa(iv)
}

/**
 * 派生密钥
 * @param {string} deviceUID - 设备唯一ID
 * @param {string} salt - 盐值
 * @param {string} level - 加密等级
 * @returns {string} 16字节密钥
 */
function deriveKey(deviceUID, salt, level) {
  const baseKey = `${deviceUID}-${salt}-${level}`

  // 简化版密钥派生（使用FNV-1a哈希）
  let hash1 = 0x811c9dc5
  let hash2 = 0x01000193

  for (let i = 0; i < baseKey.length; i++) {
    const char = baseKey.charCodeAt(i)
    hash1 ^= char
    hash1 = (hash1 * 0x01000193) >>> 0
    hash2 ^= char
    hash2 = (hash2 * 0x01000193) >>> 0
  }

  // 组合两个哈希值生成16字节密钥
  const keyPart1 = hash1.toString(16).padStart(8, '0')
  const keyPart2 = hash2.toString(16).padStart(8, '0')

  return keyPart1 + keyPart2
}

/**
 * 初始化加密引擎
 * @param {string} deviceUID - 设备唯一ID
 * @returns {boolean} 是否初始化成功
 */
export function initCrypto(deviceUID) {
  try {
    if (!deviceUID) {
      logger.error('设备UID不能为空')
      return false
    }

    keyHierarchy[ENCRYPT_LEVELS.L1] = deriveKey(deviceUID, 'posture-stats-salt', 'L1')
    keyHierarchy[ENCRYPT_LEVELS.L2] = deriveKey(deviceUID, 'health-privacy-salt', 'L2')

    isInitialized = true
    logger.info('加密引擎初始化成功', { deviceUID: deviceUID.substring(0, 8) + '...' })
    return true
  } catch (error) {
    logger.error('加密引擎初始化失败', { error: error.message })
    return false
  }
}

/**
 * 加密数据
 * @param {*} data - 待加密数据
 * @param {string} level - 加密等级
 * @returns {Object} 加密结果
 */
export function encrypt(data, level = ENCRYPT_LEVELS.L1) {
  if (!isInitialized) {
    logger.error('加密引擎未初始化')
    throw new Error('加密引擎未初始化')
  }

  const key = keyHierarchy[level]
  if (!key) {
    logger.error('无效的加密等级', { level })
    throw new Error(`无效的加密等级: ${level}`)
  }

  try {
    const cipher = new AESCipher(key)
    const iv = generateIV()
    const plaintext = safeJsonStringify(data)

    const result = cipher.encrypt(plaintext, iv)

    logger.debug('数据加密成功', {
      level,
      dataLength: plaintext.length,
      ciphertextLength: result.ciphertext.length
    })

    return result
  } catch (error) {
    logger.error('数据加密失败', { error: error.message, level })
    throw error
  }
}

/**
 * 解密数据
 * @param {Object} encryptedData - 加密数据
 * @param {string} level - 加密等级
 * @returns {*} 解密后的数据
 */
export function decrypt(encryptedData, level = ENCRYPT_LEVELS.L1) {
  if (!isInitialized) {
    logger.error('加密引擎未初始化')
    throw new Error('加密引擎未初始化')
  }

  const key = keyHierarchy[level]
  if (!key) {
    logger.error('无效的加密等级', { level })
    throw new Error(`无效的加密等级: ${level}`)
  }

  try {
    const cipher = new AESCipher(key)
    const plaintext = cipher.decrypt(encryptedData.ciphertext, atob(encryptedData.iv))
    const data = safeJsonParse(plaintext)

    logger.debug('数据解密成功', {
      level,
      ciphertextLength: encryptedData.ciphertext.length,
      dataLength: plaintext.length
    })

    return data
  } catch (error) {
    logger.error('数据解密失败', { error: error.message, level })
    throw error
  }
}

/**
 * 验证加密数据完整性
 * @param {Object} encryptedData - 加密数据
 * @returns {boolean} 数据是否完整
 */
export function validateEncryptedData(encryptedData) {
  return encryptedData &&
    encryptedData.ciphertext &&
    encryptedData.iv &&
    typeof encryptedData.ciphertext === 'string' &&
    typeof encryptedData.iv === 'string'
}

/**
 * 获取加密状态
 * @returns {Object} 加密状态信息
 */
export function getCryptoStatus() {
  return {
    isInitialized,
    levels: {
      [ENCRYPT_LEVELS.L1]: keyHierarchy[ENCRYPT_LEVELS.L1] !== null,
      [ENCRYPT_LEVELS.L2]: keyHierarchy[ENCRYPT_LEVELS.L2] !== null
    }
  }
}

/**
 * 清除密钥（安全销毁）
 */
export function clearKeys() {
  keyHierarchy[ENCRYPT_LEVELS.L1] = null
  keyHierarchy[ENCRYPT_LEVELS.L2] = null
  isInitialized = false
  logger.info('密钥已安全销毁')
}

/**
 * 存储管理器
 * 提供加密存储和文件管理功能
 */

import file from '@system.file'
import { encrypt, decrypt, validateEncryptedData } from './crypto-engine.js'
import { ENCRYPT_LEVELS, LIFECYCLE_POLICY, STORAGE_CONFIG, ERROR_CODES } from '../common/utils/constants.js'
import { logger } from '../common/utils/logger.js'

// 存储状态
const storageState = {
  initialized: false,
  usage: 0,
  fileCount: 0
}

/**
 * 加密存储数据
 * @param {string} key - 存储键名
 * @param {*} data - 待存储数据
 * @param {Object} options - 配置选项
 * @returns {Promise<Object>} 存储结果
 */
export function saveEncrypted(key, data, options = {}) {
  const {
    level = ENCRYPT_LEVELS.L1,
    expiryDays = 30
  } = options

  return new Promise((resolve, reject) => {
    // 参数验证
    if (!key || typeof key !== 'string') {
      logger.error('存储键名无效', { key })
      reject(new Error('存储键名无效'))
      return
    }

    if (data === undefined || data === null) {
      logger.error('存储数据无效', { key })
      reject(new Error('存储数据无效'))
      return
    }

    try {
      const encrypted = encrypt(data, level)
      const metadata = {
        createTime: Date.now(),
        expiryTime: Date.now() + expiryDays * 24 * 60 * 60 * 1000,
        level,
        iv: encrypted.iv,
        version: '1.0'
      }

      const fileData = {
        ciphertext: encrypted.ciphertext,
        metadata
      }

      const uri = `internal://files/${key}.enc`
      const fileContent = JSON.stringify(fileData)

      file.writeText({
        uri,
        text: fileContent,
        success: () => {
          storageState.usage += fileContent.length
          storageState.fileCount++

          logger.info('数据加密存储成功', {
            key,
            level,
            size: fileContent.length,
            expiryTime: new Date(metadata.expiryTime).toISOString()
          })

          resolve(metadata)
        },
        fail: (data, code) => {
          const error = new Error(`存储失败: ${code}`)
          logger.error('数据存储失败', { key, code, error: error.message })
          reject(error)
        }
      })
    } catch (error) {
      logger.error('数据加密失败', { key, error: error.message })
      reject(error)
    }
  })
}

/**
 * 解密读取数据
 * @param {string} key - 存储键名
 * @returns {Promise<Object>} 读取结果
 */
export function loadEncrypted(key) {
  return new Promise((resolve, reject) => {
    // 参数验证
    if (!key || typeof key !== 'string') {
      logger.error('存储键名无效', { key })
      reject(new Error('存储键名无效'))
      return
    }

    const uri = `internal://files/${key}.enc`

    file.readText({
      uri,
      success: (data) => {
        try {
          const fileData = JSON.parse(data.text)

          // 验证数据结构
          if (!validateEncryptedData(fileData)) {
            logger.error('加密数据格式无效', { key })
            reject(new Error('加密数据格式无效'))
            return
          }

          // 检查是否过期
          if (Date.now() > fileData.metadata.expiryTime) {
            logger.warn('数据已过期', {
              key,
              expiryTime: new Date(fileData.metadata.expiryTime).toISOString()
            })
            resolve({ expired: true, data: null, metadata: fileData.metadata })
            return
          }

          // 解密数据
          const decrypted = decrypt({
            ciphertext: fileData.ciphertext,
            iv: fileData.metadata.iv
          }, fileData.metadata.level)

          logger.debug('数据解密读取成功', {
            key,
            level: fileData.metadata.level,
            dataSize: JSON.stringify(decrypted).length
          })

          resolve({
            expired: false,
            data: decrypted,
            metadata: fileData.metadata
          })
        } catch (error) {
          logger.error('数据解析失败', { key, error: error.message })
          reject(error)
        }
      },
      fail: (data, code) => {
        if (code === 203) {
          // 文件不存在
          logger.debug('数据文件不存在', { key })
          resolve({ expired: false, data: null, metadata: null })
        } else {
          const error = new Error(`读取失败: ${code}`)
          logger.error('数据读取失败', { key, code, error: error.message })
          reject(error)
        }
      }
    })
  })
}

/**
 * 删除文件
 * @param {string} key - 存储键名
 * @returns {Promise<void>}
 */
export function deleteFile(key) {
  return new Promise((resolve, reject) => {
    // 参数验证
    if (!key || typeof key !== 'string') {
      logger.error('存储键名无效', { key })
      reject(new Error('存储键名无效'))
      return
    }

    const uri = `internal://files/${key}.enc`

    file.delete({
      uri,
      success: () => {
        storageState.fileCount = Math.max(0, storageState.fileCount - 1)

        logger.info('数据文件删除成功', { key })
        resolve()
      },
      fail: (data, code) => {
        const error = new Error(`删除失败: ${code}`)
        logger.error('数据文件删除失败', { key, code, error: error.message })
        reject(error)
      }
    })
  })
}

/**
 * 清理过期数据
 * @returns {Promise<Object>} 清理结果
 */
export async function cleanupExpiredData() {
  const results = {
    checked: 0,
    deleted: 0,
    errors: 0
  }

  logger.info('开始清理过期数据')

  for (const [dataType, policy] of Object.entries(LIFECYCLE_POLICY)) {
    try {
      results.checked++

      const result = await loadEncrypted(dataType)
      if (result.expired) {
        await deleteFile(dataType)
        results.deleted++
        logger.info('过期数据已清理', { dataType })
      }
    } catch (error) {
      results.errors++
      logger.error('清理过期数据失败', { dataType, error: error.message })
    }
  }

  logger.info('过期数据清理完成', results)
  return results
}

/**
 * 获取存储使用情况
 * @returns {Promise<Object>} 存储使用信息
 */
export function getStorageUsage() {
  return new Promise((resolve) => {
    file.list({
      uri: 'internal://files/',
      success: (data) => {
        const files = data.fileList || []
        let totalSize = 0

        for (const file of files) {
          if (file.uri && file.uri.endsWith('.enc')) {
            totalSize += file.size || 0
          }
        }

        const usage = {
          fileCount: files.length,
          totalSize,
          formattedSize: formatFileSize(totalSize),
          maxSize: STORAGE_CONFIG.MAX_STORAGE_SIZE,
          maxFormattedSize: formatFileSize(STORAGE_CONFIG.MAX_STORAGE_SIZE),
          usagePercent: ((totalSize / STORAGE_CONFIG.MAX_STORAGE_SIZE) * 100).toFixed(2)
        }

        logger.debug('存储使用情况', usage)
        resolve(usage)
      },
      fail: (data, code) => {
        logger.error('获取存储使用情况失败', { code })
        resolve({
          fileCount: 0,
          totalSize: 0,
          formattedSize: '0B',
          maxSize: STORAGE_CONFIG.MAX_STORAGE_SIZE,
          maxFormattedSize: formatFileSize(STORAGE_CONFIG.MAX_STORAGE_SIZE),
          usagePercent: '0'
        })
      }
    })
  })
}

/**
 * 格式化文件大小
 * @param {number} bytes - 字节数
 * @returns {string} 格式化后的大小
 */
function formatFileSize(bytes) {
  if (bytes === 0) return '0B'

  const units = ['B', 'KB', 'MB', 'GB']
  const k = 1024
  const i = Math.floor(Math.log(bytes) / Math.log(k))
  const size = (bytes / Math.pow(k, i)).toFixed(2)

  return `${size} ${units[i]}`
}

/**
 * 检查存储空间是否充足
 * @param {number} requiredSize - 需要的空间大小
 * @returns {Promise<boolean>} 是否充足
 */
export async function checkStorageSpace(requiredSize = 1024) {
  const usage = await getStorageUsage()
  const available = usage.maxSize - usage.totalSize

  const is充足 = available >= requiredSize

  if (!is充足) {
    logger.warn('存储空间不足', {
      required: formatFileSize(requiredSize),
      available: usage.formattedSize
    })
  }

  return is充足
}

/**
 * 获取存储状态
 * @returns {Object} 存储状态
 */
export function getStorageState() {
  return { ...storageState }
}

