import vibrator from '@system.vibrator'
import prompt from '@system.prompt'
import { POSTURE_LABELS, SENSOR_CONFIG, ERROR_CODES } from '../common/utils/constants.js'
import { logger } from '../common/utils/logger.js'

// 提醒状态
const reminderState = {
  lastReminderTime: 0,
  reminderCount: 0,
  isReminderActive: false
}

// 提醒消息模板
const REMINDER_MESSAGES = {
  head_down: {
    title: '体态提醒',
    message: '检测到低头前倾，请抬头活动颈椎',
    icon: '📱'
  },
  sedentary: {
    title: '体态提醒',
    message: '检测到久坐伏案，请起身活动',
    icon: '🪑'
  },
  cross_legs: {
    title: '体态提醒',
    message: '检测到跷二郎腿，请调整坐姿',
    icon: '🦵'
  },
  normal: {
    title: '体态正常',
    message: '当前体态正常，继续保持',
    icon: '✅'
  }
}

/**
 * 触发震动提醒
 * @param {Object} options - 震动选项
 * @returns {Promise<boolean>} 是否成功
 */
export function vibrateReminder(options = {}) {
  const {
    mode = 'short',
    duration = 200
  } = options

  return new Promise((resolve) => {
    // 检查是否在冷却时间内
    const now = Date.now()
    if (now - reminderState.lastReminderTime < SENSOR_CONFIG.COOLDOWN_TIME) {
      logger.debug('震动提醒被冷却时间阻止')
      resolve(false)
      return
    }

    vibrator.vibrate({
      mode,
      duration,
      success: () => {
        logger.info('震动提醒触发成功', { mode, duration })
        reminderState.lastReminderTime = now
        reminderState.reminderCount++
        resolve(true)
      },
      fail: (data, code) => {
        logger.error('震动提醒触发失败', { code, data })
        // 即使震动失败，也记录提醒时间
        reminderState.lastReminderTime = now
        resolve(false)
      }
    })
  })
}

/**
 * 显示弹窗提醒
 * @param {string} postureType - 体态类型
 * @param {Object} options - 弹窗选项
 * @returns {Promise<boolean>} 是否成功
 */
export function showReminderDialog(postureType, options = {}) {
  const {
    title = '体态提醒',
    duration = 3000
  } = options

  return new Promise((resolve) => {
    const messageConfig = REMINDER_MESSAGES[postureType] || REMINDER_MESSAGES.normal

    prompt.showDialog({
      title: title || messageConfig.title,
      message: messageConfig.message,
      buttons: [{ text: '知道了', style: 'default' }],
      success: () => {
        logger.info('弹窗提醒显示成功', { postureType })
        resolve(true)
      },
      cancel: () => {
        logger.debug('弹窗提醒被取消', { postureType })
        resolve(false)
      }
    })
  })
}

/**
 * 完整提醒流程
 * @param {string} postureType - 体态类型
 * @param {Object} options - 提醒选项
 * @returns {Promise<Object>} 提醒结果
 */
export async function triggerReminder(postureType, options = {}) {
  const {
    enableVibrate = true,
    enableDialog = true,
    vibrateOptions = {},
    dialogOptions = {}
  } = options

  const startTime = Date.now()
  const results = {
    postureType,
    timestamp: startTime,
    vibrateSuccess: false,
    dialogSuccess: false,
    duration: 0
  }

  logger.info('开始触发体态提醒', { postureType, options })

  try {
    // 1. 触发震动
    if (enableVibrate) {
      results.vibrateSuccess = await vibrateReminder(vibrateOptions)
    }

    // 2. 显示弹窗
    if (enableDialog) {
      results.dialogSuccess = await showReminderDialog(postureType, dialogOptions)
    }

    // 3. 更新状态
    reminderState.isReminderActive = true

    // 4. 记录提醒事件
    const duration = Date.now() - startTime
    results.duration = duration

    logger.info('体态提醒触发完成', {
      postureType,
      vibrateSuccess: results.vibrateSuccess,
      dialogSuccess: results.dialogSuccess,
      duration
    })

    return results
  } catch (error) {
    logger.error('体态提醒触发异常', { postureType, error: error.message })
    results.error = error.message
    return results
  } finally {
    reminderState.isReminderActive = false
  }
}

/**
 * 批量提醒
 * @param {Array} postureTypes - 体态类型数组
 * @param {Object} options - 提醒选项
 * @returns {Promise<Array>} 提醒结果数组
 */
export async function triggerBatchReminder(postureTypes, options = {}) {
  const results = []

  for (const postureType of postureTypes) {
    const result = await triggerReminder(postureType, options)
    results.push(result)

    // 添加延迟，避免提醒过于频繁
    await new Promise(resolve => setTimeout(resolve, 500))
  }

  logger.info('批量提醒完成', {
    count: results.length,
    successCount: results.filter(r => r.vibrateSuccess || r.dialogSuccess).length
  })

  return results
}

/**
 * 获取提醒状态
 * @returns {Object} 提醒状态
 */
export function getReminderState() {
  return { ...reminderState }
}

/**
 * 重置提醒状态
 */
export function resetReminderState() {
  reminderState.lastReminderTime = 0
  reminderState.reminderCount = 0
  reminderState.isReminderActive = false
  logger.info('提醒状态已重置')
}

/**
 * 检查是否可以触发提醒
 * @returns {boolean} 是否可以触发
 */
export function canTriggerReminder() {
  const now = Date.now()
  const canTrigger = now - reminderState.lastReminderTime >= SENSOR_CONFIG.COOLDOWN_TIME

  if (!canTrigger) {
    logger.debug('提醒冷却中', {
      lastReminder: new Date(reminderState.lastReminderTime).toISOString(),
      cooldownEnd: new Date(reminderState.lastReminderTime + SENSOR_CONFIG.COOLDOWN_TIME).toISOString()
    })
  }

  return canTrigger
}

/**
 * 获取提醒配置
 * @param {string} postureType - 体态类型
 * @returns {Object} 提醒配置
 */
export function getReminderConfig(postureType) {
  return REMINDER_MESSAGES[postureType] || REMINDER_MESSAGES.normal
}

/**
 * 设置自定义提醒消息
 * @param {string} postureType - 体态类型
 * @param {Object} messageConfig - 消息配置
