/**
 * 格式化数据生命周期显示
 * @param {Object} lifecycle - 生命周期数据
 * @returns {Object} 格式化后的显示信息
 */
export function formatLifecycleDisplay(lifecycle) {
  const items = []

  for (const [dataType, policy] of Object.entries(lifecycle)) {
    const remainingDays = Math.max(0, policy.retentionDays - Math.floor((Date.now() - policy.createTime) / (24 * 60 * 60 * 1000)))
    const progress = Math.min(100, ((policy.retentionDays - remainingDays) / policy.retentionDays) * 100)

    items.push({
      dataType,
      retentionDays: policy.retentionDays,
      remainingDays,
      progress: progress.toFixed(2),
      status: remainingDays > 0 ? 'active' : 'expired'
    })
  }

  return items
}

/**
 * 验证用户输入
 * @param {string} input - 用户输入
 * @param {Object} rules - 验证规则
 * @returns {Object} 验证结果
 */
export function validateUserInput(input, rules = {}) {
  const {
    required = false,
    minLength = 0,
    maxLength = Infinity,
    pattern = null
  } = rules

  const errors = []

  if (required && (!input || input.trim() === '')) {
    errors.push('此字段为必填项')
  }

  if (input && input.length < minLength) {
    errors.push(`长度不能少于${minLength}个字符`)
  }

  if (input && input.length > maxLength) {
    errors.push(`长度不能超过${maxLength}个字符`)
  }

  if (input && pattern && !pattern.test(input)) {
    errors.push('格式不正确')
  }

  return {
    valid: errors.length === 0,
    errors
  }
}

