/**
 * 安全管理器
 * 提供统一的安全功能和数据保护
 */

import { ENCRYPT_LEVELS, LIFECYCLE_POLICY, ERROR_CODES } from './utils/constants.js'
import { logger } from './utils/logger.js'
import { initCrypto, clearKeys, getCryptoStatus } from '../modules/crypto-engine.js'
import { saveEncrypted, loadEncrypted, deleteFile, cleanupExpiredData } from '../modules/storage-manager.js'

// 安全状态
const securityState = {
  initialized: false,
  deviceUID: null,
  lastSecurityCheck: 0,
  securityEvents: []
}

// 安全配置
const SECURITY_CONFIG = {
  MAX_DEVICE_UID_LENGTH: 64,
  DEVICE_UID_PATTERN: /^[a-zA-Z0-9\-_]+$/,
  SECURITY_CHECK_INTERVAL: 5 * 60 * 1000, // 5分钟
  MAX_SECURITY_EVENTS: 100
}

/**
 * 初始化安全管理器
 * @param {string} deviceUID - 设备唯一ID
 * @returns {Promise<boolean>} 是否初始化成功
 */
export async function initSecurityManager(deviceUID) {
  try {
    // 参数验证
    if (!deviceUID || typeof deviceUID !== 'string') {
      logger.error('设备UID无效')
      return false
    }

    if (deviceUID.length > SECURITY_CONFIG.MAX_DEVICE_UID_LENGTH) {
      logger.error('设备UID过长', { length: deviceUID.length })
      return false
    }

    if (!SECURITY_CONFIG.DEVICE_UID_PATTERN.test(deviceUID)) {
      logger.error('设备UID格式无效')
      return false
    }

    // 初始化加密引擎
    const cryptoInitialized = initCrypto(deviceUID)
    if (!cryptoInitialized) {
      logger.error('加密引擎初始化失败')
      return false
    }

    // 更新安全状态
    securityState.initialized = true
    securityState.deviceUID = deviceUID
    securityState.lastSecurityCheck = Date.now()

    // 记录安全事件
    recordSecurityEvent('INIT', '安全管理器初始化成功')

    logger.info('安全管理器初始化成功', { deviceUID: deviceUID.substring(0, 8) + '...' })
    return true
  } catch (error) {
    logger.error('安全管理器初始化异常', { error: error.message })
    return false
  }
}

/**
 * 记录安全事件
 * @param {string} eventType - 事件类型
 * @param {string} description - 事件描述
 * @param {Object} details - 事件详情
 */
function recordSecurityEvent(eventType, description, details = null) {
  const event = {
    timestamp: Date.now(),
    type: eventType,
    description,
    details
  }

  securityState.securityEvents.push(event)

  // 限制事件数量
  if (securityState.securityEvents.length > SECURITY_CONFIG.MAX_SECURITY_EVENTS) {
    securityState.securityEvents.shift()
  }

  logger.debug('安全事件记录', event)
}

/**
 * 安全保存数据
 * @param {string} key - 存储键名
 * @param {*} data - 待存储数据
 * @param {Object} options - 配置选项
 * @returns {Promise<Object>} 保存结果
 */
export async function secureSave(key, data, options = {}) {
  if (!securityState.initialized) {
    logger.error('安全管理器未初始化')
    throw new Error('安全管理器未初始化')
  }

  try {
    // 数据脱敏处理（如果需要）
    const processedData = await preprocessDataForStorage(data, options)

    // 加密保存
    const result = await saveEncrypted(key, processedData, options)

    // 记录安全事件
    recordSecurityEvent('SAVE', `安全保存数据: ${key}`, {
      level: options.level,
      expiryDays: options.expiryDays
    })

    return result
  } catch (error) {
    recordSecurityEvent('SAVE_ERROR', `数据保存失败: ${key}`, {
      error: error.message
    })
    throw error
  }
}

/**
 * 安全读取数据
 * @param {string} key - 存储键名
 * @returns {Promise<Object>} 读取结果
 */
export async function secureLoad(key) {
  if (!securityState.initialized) {
    logger.error('安全管理器未初始化')
    throw new Error('安全管理器未初始化')
  }

  try {
    const result = await loadEncrypted(key)

    // 记录安全事件
    recordSecurityEvent('LOAD', `安全读取数据: ${key}`, {
      expired: result.expired,
      hasData: result.data !== null
    })

    return result
  } catch (error) {
    recordSecurityEvent('LOAD_ERROR', `数据读取失败: ${key}`, {
      error: error.message
    })
    throw error
  }
}

/**
 * 预处理数据（脱敏）
 * @param {*} data - 原始数据
 * @param {Object} options - 配置选项
 * @returns {*} 处理后的数据
 */
async function preprocessDataForStorage(data, options) {
  // 根据数据类型进行脱敏处理
  if (options.desensitize && options.dataType) {
    const { desensitize } = await import('../modules/desensitizer.js')
    return desensitize(data, options.dataType)
  }

  return data
}

/**
 * 执行安全检查
 * @returns {Promise<Object>} 检查结果
 */
export async function performSecurityCheck() {
  const results = {
    timestamp: Date.now(),
    checks: [],
    passed: true
  }

  try {
    // 1. 检查加密引擎状态
    const cryptoStatus = getCryptoStatus()
    results.checks.push({
      name: '加密引擎',
      status: cryptoStatus.isInitialized ? 'PASS' : 'FAIL',
      details: cryptoStatus
    })

    if (!cryptoStatus.isInitialized) {
      results.passed = false
    }

    // 2. 检查存储空间
    const { getStorageUsage } = await import('../modules/storage-manager.js')
    const storageUsage = await getStorageUsage()
    const storageOk = parseFloat(storageUsage.usagePercent) < 90

    results.checks.push({
      name: '存储空间',
      status: storageOk ? 'PASS' : 'WARN',
      details: storageUsage
    })

    // 3. 清理过期数据
    const cleanupResult = await cleanupExpiredData()
    results.checks.push({
      name: '过期数据清理',
      status: cleanupResult.errors === 0 ? 'PASS' : 'WARN',
      details: cleanupResult
    })

    // 更新安全状态
    securityState.lastSecurityCheck = Date.now()

    // 记录安全事件
    recordSecurityEvent('SECURITY_CHECK', '安全检查完成', {
      passed: results.passed,
      checkCount: results.checks.length
    })

    logger.info('安全检查完成', {
      passed: results.passed,
      checkCount: results.checks.length
    })

    return results
  } catch (error) {
    results.passed = false
    results.error = error.message

    recordSecurityEvent('SECURITY_CHECK_ERROR', '安全检查失败', {
      error: error.message
    })

    logger.error('安全检查失败', { error: error.message })
    return results
  }
}

/**
 * 获取安全状态
 * @returns {Object} 安全状态
 */
export function getSecurityState() {
  return {
    ...securityState,
    cryptoStatus: getCryptoStatus()
  }
}

/**
 * 获取安全事件历史
 * @param {number} limit - 限制数量
 * @returns {Array} 安全事件历史
 */
export function getSecurityEvents(limit = 50) {
  return securityState.securityEvents.slice(-limit)
}

/**
 * 清除安全事件历史
 */
export function clearSecurityEvents() {
  securityState.securityEvents = []
  logger.info('安全事件历史已清空')
}

/**
 * 安全销毁数据
 * @param {string} key - 存储键名
 * @returns {Promise<boolean>} 是否成功
 */
export async function secureDestroy(key) {
  try {
    // 先读取数据，记录销毁事件
    const data = await loadEncrypted(key)
    if (data.data) {
      recordSecurityEvent('DESTROY', `销毁数据: ${key}`, {
        hadData: true
      })
    }

    // 删除文件
    await deleteFile(key)

    // 覆写清零（如果配置了）
    // 注意：由于文件系统限制，这里只能删除文件
    // 实际的覆写清零需要底层文件系统支持

    logger.info('数据安全销毁完成', { key })
    return true
  } catch (error) {
    logger.error('数据安全销毁失败', { key, error: error.message })
    return false
  }
}

/**
 * 清除所有安全数据
 * @returns {Promise<Object>} 清除结果
 */
export async function clearAllSecurityData() {
  const results = {
    deleted: 0,
    errors: 0
  }

  try {
    // 清理所有加密文件
    const cleanupResult = await cleanupExpiredData()
    results.deleted = cleanupResult.deleted
    results.errors = cleanupResult.errors

    // 清除密钥
    clearKeys()

    // 重置安全状态
    securityState.initialized = false
    securityState.deviceUID = null
    securityState.lastSecurityCheck = 0
    securityState.securityEvents = []

    // 记录安全事件
    recordSecurityEvent('CLEAR_ALL', '所有安全数据已清除')

    logger.info('所有安全数据已清除', results)
    return results
  } catch (error) {
    logger.error('清除安全数据失败', { error: error.message })
    results.errors++
    return results
  }
}

/**
 * 生成安全报告
 * @returns {Object} 安全报告
 */
export function generateSecurityReport() {
  return {
    timestamp: Date.now(),
    status: securityState.initialized ? 'ACTIVE' : 'INACTIVE',
    deviceUID: securityState.deviceUID ? securityState.deviceUID.substring(0, 8) + '...' : null,
    cryptoStatus: getCryptoStatus(),
    lastSecurityCheck: securityState.lastSecurityCheck,
