    recentEvents: securityState.securityEvents.slice(-10)
  }
}

/**
 * 配置管理器
 * 统一管理项目配置和用户设置
 */

import { STORAGE_CONFIG, SENSOR_CONFIG, POWER_CONFIG, UI_CONFIG } from './utils/constants.js'
import { logger } from './utils/logger.js'
import { deepClone, safeJsonStringify, safeJsonParse } from './utils/helpers.js'

// 默认配置
const DEFAULT_CONFIG = {
  // 监测设置
  monitoring: {
    enabled: false,
    sensitivity: 'medium', // low/medium/high
    samplingRate: SENSOR_CONFIG.SAMPLING_RATE,
    windowSize: SENSOR_CONFIG.WINDOW_SIZE
  },

  // 提醒设置
  reminder: {
    vibrateEnabled: true,
    dialogEnabled: true,
    cooldownMinutes: SENSOR_CONFIG.COOLDOWN_TIME / 60000
  },

  // 数据管理
  dataManagement: {
    retentionDays: 30,
    autoCleanup: true,
    maxStorageSize: STORAGE_CONFIG.MAX_STORAGE_SIZE
  },

  // 功耗设置
  power: {
    backgroundSamplingRate: POWER_CONFIG.BACKGROUND_RATE,
    staticSamplingRate: POWER_CONFIG.STATIC_RATE,
    nightModeEnabled: true,
    nightModeStart: POWER_CONFIG.NIGHT_MODE_START,
    nightModeEnd: POWER_CONFIG.NIGHT_MODE_END
  },

  // UI设置
  ui: {
    designWidth: UI_CONFIG.DESIGN_WIDTH,
    animationEnabled: true,
    language: 'zh-CN'
  },

  // 安全设置
  security: {
    encryptionEnabled: true,
    autoDestroyEnabled: true,
    securityCheckInterval: 5 // 分钟
  },

  // 版本信息
  version: '1.0.0',
  lastUpdated: null
}

// 当前配置
let currentConfig = deepClone(DEFAULT_CONFIG)

// 配置变更监听器
const configListeners = []

/**
 * 获取配置
 * @param {string} key - 配置键名（可选，支持点号分隔的嵌套键名）
 * @returns {*} 配置值
 */
export function getConfig(key = null) {
  if (!key) {
    return deepClone(currentConfig)
  }

  // 支持点号分隔的嵌套键名
  const keys = key.split('.')
  let value = currentConfig

  for (const k of keys) {
    if (value === null || value === undefined || typeof value !== 'object') {
      return undefined
    }
    value = value[k]
  }

  return deepClone(value)
}

/**
 * 设置配置
 * @param {string|Object} key - 配置键名或配置对象
 * @param {*} value - 配置值
 * @param {Object} options - 选项
 */
export function setConfig(key, value, options = {}) {
  const { merge = true, notify = true } = options

  if (typeof key === 'object') {
    // 批量设置
    for (const [k, v] of Object.entries(key)) {
      setConfig(k, v, { merge, notify: false })
    }
    if (notify) {
      notifyConfigChange()
    }
    return
  }

  // 支持点号分隔的嵌套键名
  const keys = key.split('.')
  let target = currentConfig

  for (let i = 0; i < keys.length - 1; i++) {
    const k = keys[i]
    if (target[k] === undefined || typeof target[k] !== 'object') {
      target[k] = {}
    }
    target = target[k]
  }

  const lastKey = keys[keys.length - 1]

  // 合并对象
  if (merge && typeof target[lastKey] === 'object' && typeof value === 'object') {
    target[lastKey] = { ...target[lastKey], ...value }
  } else {
    target[lastKey] = value
  }

  // 更新时间戳
  currentConfig.lastUpdated = Date.now()

  // 通知配置变更
  if (notify) {
    notifyConfigChange(key, value)
  }

  logger.debug('配置已更新', { key, value })
}

/**
 * 重置配置
 * @param {string} key - 配置键名（可选，不传则重置所有配置）
 */
export function resetConfig(key = null) {
  if (!key) {
    currentConfig = deepClone(DEFAULT_CONFIG)
    logger.info('所有配置已重置')
  } else {
    const defaultValue = getConfigFromDefault(key)
    if (defaultValue !== undefined) {
      setConfig(key, defaultValue)
      logger.info('配置已重置', { key })
    }
  }

  notifyConfigChange()
}

/**
 * 从默认配置获取值
 * @param {string} key - 配置键名
 * @returns {*} 默认值
 */
function getConfigFromDefault(key) {
  const keys = key.split('.')
  let value = DEFAULT_CONFIG

  for (const k of keys) {
    if (value === null || value === undefined || typeof value !== 'object') {
      return undefined
    }
    value = value[k]
  }

  return deepClone(value)
}

/**
 * 验证配置
 * @param {Object} config - 要验证的配置
 * @returns {Object} 验证结果
 */
export function validateConfig(config) {
  const errors = []

  // 验证监测设置
  if (config.monitoring) {
    if (config.monitoring.sensitivity && !['low', 'medium', 'high'].includes(config.monitoring.sensitivity)) {
      errors.push('监测灵敏度无效')
    }
    if (config.monitoring.samplingRate && (config.monitoring.samplingRate < 1 || config.monitoring.samplingRate > 100)) {
      errors.push('采样率无效')
    }
  }

  // 验证提醒设置
  if (config.reminder) {
    if (config.reminder.cooldownMinutes && config.reminder.cooldownMinutes < 0) {
      errors.push('冷却时间无效')
    }
  }

  // 验证数据管理设置
  if (config.dataManagement) {
    if (config.dataManagement.retentionDays && config.dataManagement.retentionDays < 1) {
      errors.push('数据保留时长无效')
    }
  }

  // 验证功耗设置
  if (config.power) {
    if (config.power.nightModeStart && (config.power.nightModeStart < 0 || config.power.nightModeStart > 23)) {
      errors.push('夜间模式开始时间无效')
    }
    if (config.power.nightModeEnd && (config.power.nightModeEnd < 0 || config.power.nightModeEnd > 23)) {
      errors.push('夜间模式结束时间无效')
    }
  }

  return {
    valid: errors.length === 0,
    errors
  }
}

/**
 * 导出配置
 * @returns {string} JSON格式的配置
 */
export function exportConfig() {
  return safeJsonStringify(currentConfig, '{}')
}

/**
 * 导入配置
 * @param {string} configJson - JSON格式的配置
 * @returns {boolean} 是否成功
 */
export function importConfig(configJson) {
  const config = safeJsonParse(configJson)
  if (!config) {
    logger.error('配置导入失败：无效的JSON格式')
    return false
  }

  // 验证配置
  const validation = validateConfig(config)
  if (!validation.valid) {
    logger.error('配置导入失败：验证失败', { errors: validation.errors })
    return false
  }

  // 合并配置
  setConfig(config)
  logger.info('配置导入成功')
  return true
}

/**
 * 添加配置变更监听器
 * @param {Function} listener - 监听器函数
 * @returns {Function} 取消监听函数
 */
export function addConfigListener(listener) {
  configListeners.push(listener)

  return () => {
    const index = configListeners.indexOf(listener)
    if (index > -1) {
      configListeners.splice(index, 1)
    }
  }
}

/**
 * 通知配置变更
 * @param {string} key - 变更的配置键名
 * @param {*} value - 变更的配置值
 */
function notifyConfigChange(key = null, value = null) {
  const config = deepClone(currentConfig)

  for (const listener of configListeners) {
    try {
      listener(config, key, value)
    } catch (error) {
      logger.error('配置变更监听器执行错误', { error: error.message })
    }
  }
}

/**
 * 获取配置摘要
 * @returns {Object} 配置摘要
 */
export function getConfigSummary() {
  return {
    monitoring: {
      enabled: currentConfig.monitoring.enabled,
      sensitivity: currentConfig.monitoring.sensitivity
    },
    reminder: {
      vibrateEnabled: currentConfig.reminder.vibrateEnabled,
      dialogEnabled: currentConfig.reminder.dialogEnabled
    },
    dataManagement: {
      retentionDays: currentConfig.dataManagement.retentionDays,
      autoCleanup: currentConfig.dataManagement.autoCleanup
    },
    power: {
      nightModeEnabled: currentConfig.power.nightModeEnabled
    },
    version: currentConfig.version,
    lastUpdated: currentConfig.lastUpdated
  }
}

/**
 * 获取敏感度配置
 * @param {string} sensitivity - 敏感度级别
 * @returns {Object} 敏感度配置
 */
export function getSensitivityConfig(sensitivity) {
  const configs = {
    low: {
      confidenceThreshold: 0.6,
      cooldownTime: 10 * 60 * 1000, // 10分钟
      windowSize: 150
    },
    medium: {
      confidenceThreshold: 0.75,
      cooldownTime: 5 * 60 * 1000, // 5分钟
      windowSize: 100
    },
    high: {
      confidenceThreshold: 0.85,
      cooldownTime: 2 * 60 * 1000, // 2分钟
      windowSize: 50
    }
  }

  return configs[sensitivity] || configs.medium
}

/**
 * 测试工具
 * 提供自动化测试功能
 */

import { logger, LOG_LEVELS } from './utils/logger.js'

// 测试结果
const testResults = {
  passed: 0,
  failed: 0,
  skipped: 0,
  total: 0,
  tests: [],
  startTime: null,
  endTime: null
}

/**
 * 测试套件
 * @param {string} name - 测试套件名称
 * @param {Function} callback - 测试回调函数
 */
export function describe(name, callback) {
  logger.info(`测试套件: ${name}`)
  testResults.startTime = Date.now()

  try {
    callback()
  } catch (error) {
    logger.error(`测试套件执行失败: ${name}`, { error: error.message })
  }
}

/**
 * 测试用例
 * @param {string} name - 测试用例名称
 * @param {Function} callback - 测试回调函数
 */
export function it(name, callback) {
  testResults.total++
  const testResult = {
    name,
    status: 'pending',
    duration: 0,
    error: null
  }

  const startTime = Date.now()

  try {
    callback()
    testResult.status = 'passed'
    testResults.passed++
    logger.debug(`✓ ${name}`)
  } catch (error) {
    testResult.status = 'failed'
    testResult.error = error.message
    testResults.failed++
    logger.error(`✗ ${name}`, { error: error.message })
  }

  testResult.duration = Date.now() - startTime
  testResults.tests.push(testResult)
}

/**
 * 断言：相等
 * @param {*} actual - 实际值
 * @param {*} expected - 期望值
 * @param {string} message - 错误消息
 */
export function expectEqual(actual, expected, message = '') {
  if (actual !== expected) {
    throw new Error(`${message ? message + ': ' : ''}期望 ${expected}，实际 ${actual}`)
  }
}

/**
 * 断言：不相等
 * @param {*} actual - 实际值
 * @param {*} expected - 期望值
 * @param {string} message - 错误消息
 */
export function expectNotEqual(actual, expected, message = '') {
  if (actual === expected) {
    throw new Error(`${message ? message + ': ' : ''}期望不等于 ${expected}`)
  }
}

/**
 * 断言：深度相等
 * @param {*} actual - 实际值
 * @param {*} expected - 期望值
 * @param {string} message - 错误消息
 */
export function expectDeepEqual(actual, expected, message = '') {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) {
    throw new Error(`${message ? message + ': ' : ''}期望深度相等\n期望: ${JSON.stringify(expected)}\n实际: ${JSON.stringify(actual)}`)
  }
}

/**
 * 断言：为真
 * @param {*} value - 要验证的值
 * @param {string} message - 错误消息
 */
export function expectTrue(value, message = '') {
  if (!value) {
    throw new Error(`${message ? message + ': ' : ''}期望为真，实际为假`)
  }
}

/**
 * 断言：为假
 * @param {*} value - 要验证的值
 * @param {string} message - 错误消息
 */
export function expectFalse(value, message = '') {
  if (value) {
    throw new Error(`${message ? message + ': ' : ''}期望为假，实际为真`)
  }
}

/**
 * 断言：抛出错误
 * @param {Function} fn - 要执行的函数
 * @param {string} expectedError - 期望的错误消息
 */
export function expectThrow(fn, expectedError = null) {
  try {
    fn()
    throw new Error('期望抛出错误，但没有抛出')
  } catch (error) {
    if (expectedError && error.message !== expectedError) {
      throw new Error(`期望错误消息: ${expectedError}，实际: ${error.message}`)
    }
  }
}

/**
 * 断言：不抛出错误
 * @param {Function} fn - 要执行的函数
 */
export function expectNotThrow(fn) {
  try {
    fn()
  } catch (error) {
    throw new Error(`期望不抛出错误，但抛出了: ${error.message}`)
  }
}

/**
 * 断言：包含
 * @param {string} haystack - 字符串
 * @param {string} needle - 子字符串
 * @param {string} message - 错误消息
 */
export function expectContain(haystack, needle, message = '') {
  if (!haystack.includes(needle)) {
    throw new Error(`${message ? message + ': ' : ''}期望包含 "${needle}"`)
  }
}

/**
 * 断言：数组长度
 * @param {Array} arr - 数组
 * @param {number} length - 期望长度
 * @param {string} message - 错误消息
 */
export function expectLength(arr, length, message = '') {
  if (!Array.isArray(arr) || arr.length !== length) {
    throw new Error(`${message ? message + ': ' : ''}期望数组长度为 ${length}，实际为 ${arr ? arr.length : '非数组'}`)
  }
}

/**
 * 运行测试
 * @param {Function} testSuite - 测试套件函数
 * @returns {Object} 测试结果
 */
export async function runTests(testSuite) {
  testResults.passed = 0
  testResults.failed = 0
  testResults.skipped = 0
  testResults.total = 0
  testResults.tests = []
  testResults.startTime = Date.now()

  try {
    await testSuite()
  } catch (error) {
    logger.error('测试执行失败', { error: error.message })
  }

  testResults.endTime = Date.now()
  testResults.duration = testResults.endTime - testResults.startTime

  printTestResults()

  return testResults
}

/**
 * 打印测试结果
 */
export function printTestResults() {
  const { passed, failed, skipped, total, duration } = testResults

  logger.info('测试结果:')
  logger.info(`  通过: ${passed}/${total}`)
  logger.info(`  失败: ${failed}/${total}`)
  logger.info(`  跳过: ${skipped}/${total}`)
  logger.info(`  耗时: ${duration}ms`)
  logger.info(`  成功率: ${total > 0 ? ((passed / total) * 100).toFixed(2) : 0}%`)

  if (failed > 0) {
    logger.error('失败的测试:')
    testResults.tests
      .filter(t => t.status === 'failed')
      .forEach(t => {
        logger.error(`  ✗ ${t.name}: ${t.error}`)
      })
  }
}

/**
 * 获取测试结果
 * @returns {Object} 测试结果
 */
export function getTestResults() {
  return { ...testResults }
}

/**
 * 清空测试结果
 */
export function clearTestResults() {
  testResults.passed = 0
  testResults.failed = 0
  testResults.skipped = 0
  testResults.total = 0
  testResults.tests = []
  testResults.startTime = null
  testResults.endTime = null
}

/**
 * 跳过测试
