 */
export function skip(name) {
  testResults.total++
  testResults.skipped++
  testResults.tests.push({
    name,
    status: 'skipped',
    duration: 0,
    error: null
  })
  logger.debug(`⊘ ${name} (跳过)`)
}

/**
