/**
 * Mock函数
 * @param {Function} implementation - 实现函数
 * @returns {Function} Mock函数
 */
export function createMock(implementation = () => {}) {
  const mock = function (...args) {
    mock.calls.push(args)
    mock.lastCall = args
    return implementation.apply(this, args)
  }

  mock.calls = []
  mock.lastCall = null

  mock.mockImplementation = (newImplementation) => {
    implementation = newImplementation
  }

  mock.mockReturnValue = (value) => {
    implementation = () => value
  }

  mock.mockResolvedValue = (value) => {
    implementation = () => Promise.resolve(value)
  }

  mock.mockRejectedValue = (error) => {
    implementation = () => Promise.reject(error)
  }

  mock.reset = () => {
    mock.calls = []
    mock.lastCall = null
  }

  return mock
}

/**
 * 模拟延迟
 * @param {number} ms - 延迟毫秒数
 * @returns {Promise} 延迟Promise
 */
export function mockDelay(ms) {
  return new Promise(resolve => setTimeout(resolve, ms))
}

